{"implementation":"def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_ids = []
    diagnostics = []
    for call in calls:
        call_id = call['call_id']
        gain = call['loss_without_call'] - call['loss_with_call']
        norm_gain = gain / call['prediction_tokens']
        norm_gain_rounded = round(norm_gain, 8)
        accept = call['parseable'] and norm_gain >= threshold
        if accept:
            accepted_ids.append(call_id)
        diagnostics.append({
            'accepted': accept,
            'call_id': call_id,
            'normalized_gain': norm_gain_rounded
        })
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"}
